"""Paper-only evaluations and parent resource lineage, kept apart from runnable releases."""
def populate(c):
    bend_paper(c); bgcs(c); deepd(c); parent_resources(c)

def bend_paper(c):
    e=c.ev('bend-paper-extras','bend-paper','Sections 4–6; Appendices C.1, D.2, E.1','The paper evaluates COMPASS transfer/interactions, TRIP editing efficiency and MAGE personal-sequence controls in addition to the eight packaged task IDs.')
    next(s for s in c.rows['evaluations'] if s['id']=='bend')['notes']='Eight task IDs are packaged by the inspected release. Additional paper-only analyses are linked separately and do not imply runnable release coverage. Design tasks select among measured candidates; tissue identification does not test unseen tissues.'
    c.suite('compass','COMPASS splicing assays','Single/double mutation effects and non-additive splicing interactions. BEND transfer and interaction cohorts use different gene-overlap rules.',e,status='partial')
    for slug,target,desc,caps in [('effects','Splicing mutation effect','Predict mutant-minus-reference splicing response for single/double mutants; mutation multiplicity and cell-line averaging are protocol variants.',('variant-effects',)),('interaction','Non-additive splicing interaction','Predict double-mutant effect minus the two single-mutant effects. Accurate single/double effects do not establish accurate interaction prediction.',('variant-effects','genetic-interactions'))]:
        t='compass-'+slug
        c.task(t,'compass',target,'COMPASS',target,desc,'regression','Experimental splicing assays',e,applications=('rna-engineering','variant-interpretation','gene-therapy'),capabilities=caps,regions=('splice','exon','intron'),populations=('human',),input='Reference, single-mutant and/or double-mutant assay constructs',limitations='Paper-audited BEND processing; original assay files and per-gene retained rows have not yet been independently inspected.')
        c.member('bend',t,e,'Paper-only analysis; not one of the eight packaged BEND task IDs.')
        split='For transfer, remove overlapping sequences and all 23 shared genes from both assays; fit OpenSplice 398 train /45 validation genes, evaluate 4,618 COMPASS mutations in 88 remaining genes.' if slug=='effects' else 'Train readouts on OpenSplice substitutions; exclude exact sequence overlaps but retain shared genes. Interaction analysis spans 110 COMPASS genes.'
        p=c.protocol(t,t+'-bend-probe','BEND OpenSplice-trained readout',e,'frozen probe','Mean pooled sequence features / mutant-minus-reference differences',split,'gene / source assay',metrics=(('spearman','Within gene, then mean over genes'),),embeddings=True,fitted='Regularized linear readout fit only on OpenSplice',selection='No COMPASS labels used for fitting or model selection in the transfer setting.',notes='Transfer cohort and interaction cohort are different variants. Readout calibration subtracts the unchanged-sequence prediction before computing interactions.')
        c.protocol(t,t+'-native','BEND native functional outputs',e,'zero-shot existing functional head','Existing splice-boundary probabilities / native functional outputs',split,'gene / assay',metrics=('spearman',),embeddings=False,notes='Native outputs and embedding-fitted heads are separate interfaces.')
        c.use('ntv3',t,e,'bend','external-evaluation',protocol=p,note='BEND uses earlier 100M/650M NTv3 checkpoints; this is not asserted to be the October v2 ~703M model.')
        c.use('alphagenome',t,e,'bend','external-evaluation',note='Native outputs and separate fitted-readout protocols are reported.')
    c.count('compass-effects',4618,'mutations',e,split='cross-assay transfer test',qualifier='88-gene cohort excluding 23 shared genes.')
    c.count('compass-effects',88,'genes',e,split='cross-assay transfer test')
    for value,unit in [(15035,'single-mutant measurements'),(48054,'double-mutant measurements'),(110,'genes')]:c.count('compass-interaction',value,unit,e,qualifier='Interaction cohort retains shared genes after exact-sequence exclusion.')
    c.suite('trip','TRIP editing-efficiency assays','PRIDICT2 K562 integration library; editing system is a linked condition.',e,status='partial')
    c.task('trip-efficiency','trip','Editing efficiency by integration locus','K562 TRIP / PRIDICT2','Editing efficiency','A fixed 640-bp reporter is integrated at 1,196 locations on 23 chromosomes. Predict editing efficiency from the surrounding reference genome without including the inserted reporter.','regression','Experimental prime/base/Cas9 editing measurements',e,applications=('gene-therapy','regulatory-engineering'),capabilities=('functional-prediction','context-specific'),regions=('genome',),populations=('human',),input='8-kb reference window around integration site',limitations='Context varies while reporter/editing program is fixed. Per-system count and original source artifact audit remain pending.')
    c.member('bend','trip-efficiency',e,'Paper-only Appendix C.1; not a packaged task ID.')
    p=c.protocol('trip-efficiency','trip-bend-probe','Chromosome-held-out editing probe',e,'frozen probe','Frozen sequence embedding; AlphaGenome N-pads to its supported input','Five cross-validation folds keep whole chromosomes together. Fixed ridge α=1000; alternative tuning uses three folds within training chromosomes.','chromosome',metrics=(('spearman','Combined held-out predictions; chromosome bootstrap intervals'),),embeddings=True,fitted='Separate ridge readout per editing system',selection='Alternative α selected on training chromosomes by MSE')
    for name in ('Prime editing','ABE8e-SpG','BE4max','SpCas9'):c.variant('trip-efficiency','trip-'+name.lower().replace(' ','-'),name,e,context='Editing-system condition; fixed guide/reporter program.')
    c.count('trip-efficiency',1196,'integration locations',e);c.count('trip-efficiency',23,'chromosomes',e)
    for model in ('ntv3','alphagenome'):c.use(model,'trip-efficiency',e,'bend','external-evaluation',protocol=p,note='NTv3 checkpoint generation differs from the later October v2 model.')
    c.suite('mage','MAGE personal-sequence expression','BEND evaluates personal sequence at familiar versus unseen gene regions using a one-hot linear control.',e,status='partial')
    c.task('mage-expression','mage','Personal-sequence gene-expression prediction','MAGE, BEND processed cohort','Gene expression across held-out people','Reconstruct both phased chromosome copies for 729 people and 557 chromosome-22 genes. Compare correct versus genotype-shuffled personal sequence, shuffling within population and data split.','regression','Measured human gene expression',e,applications=('target-discovery','variant-interpretation'),capabilities=('functional-prediction','context-specific'),regions=('gene','promoter'),populations=('human',),input='One-hot personal DNA with donor/assay covariates',limitations='This paper analysis is a one-hot baseline, not an established gLM result. It evaluates ancestry-related covariates and donor transfer separately from unseen gene regions.')
    c.member('bend','mage-expression',e,'Paper-only Appendix D.2; not a packaged task ID.')
    c.protocol('mage-expression','mage-personal','Seen versus unseen gene-region analysis',e,'supervised one-hot baseline','Personal DNA plus donor/assay covariates','Both settings hold out people; the second also holds out gene regions, keeping overlapping 8-kb windows together.','person and genomic-region group',metrics=(('spearman','Average within-gene Spearman; report gain over within-population genotype shuffle; Appendix A defines the group statistic'),),embeddings=False,fitted='Linear readout',notes='No model–task usage is inferred for a gLM from this baseline.')
    c.count('mage-expression',729,'people',e);c.count('mage-expression',557,'chr22 genes',e)
    # Carrying an allele and conditioning allele preference on a haplotype are distinct targets.
    eh=c.ev('bend-haplotype','bend-paper','Appendix B.3; Figure 9','512 SNP sites with REF/ALT carrier sequences; allele-preference shift uses 396 carrier pairs with different surrounding DNA.')
    for slug,target in [('recovery','Carried allele recovery'),('preference','Allele-preference shift between haplotypes')]:
        t='bend-haplotype-'+slug
        c.task(t,'bend',target,'BEND natural haplotype panel',target,'Score allele probabilities in REF/ALT carriers’ own surrounding DNA, with equal carrier weights. The preference target contrasts ALT/REF odds across carrier backgrounds.','sequence diagnostic','Phased natural allele/haplotype calls',eh,applications=('model-development',),capabilities=('sequence-modeling',) if slug=='recovery' else ('sequence-modeling','genetic-interactions'),regions=('genome',),populations=('human',),input='Personal haplotype sequences including called indels',limitations='A haplotype-conditioned allele preference is not a measured molecular epistasis label. Retained sequence files remain to be audited.')
        c.protocol(t,t+'-protocol','BEND haplotype probability diagnostic',eh,'zero-shot','Conditional base probabilities / allele log odds','39 genomic blocks; SNP sites selected without model scores. Context/calibration/query procedures differ by model.','genomic block / SNP pair',metrics=('bits',) if slug=='recovery' else (),embeddings=False)
        c.count(t,512 if slug=='recovery' else 396,'SNP sites' if slug=='recovery' else 'carrier pairs',eh)
        c.use('evo2',t,eh,'bend','external-evaluation')

def bgcs(c):
    e=c.ev('bgcs-methods','bgcs-paper','Methods: BGCs-Bench dataset and embedding evaluation; Figures 2–4','MIBiG4 active BGCs, 66k/131k length-limited cohorts, five balanced folds and frozen logistic probes on three targets.')
    next(s for s in c.rows['evaluations'] if s['id']=='bgcs')['status']='partial'
    next(s for s in c.rows['evaluations'] if s['id']=='bgcs')['notes']='Three paper/code-audited targets. Length, pooling, layer and Other-class inclusion are protocol variants; dataset rows and fold memberships still need recounting.'
    repo='GenAIBio/BGCs-Bench'
    for slug,file,target,typ,desc,regions,metric in [('biosynthetic','bgc_classification.py','Biosynthetic class','multilabel classification','Six MIBiG categories (NRPS, PKS, RiPPs, terpene, saccharide, other); include/exclude Other as an explicit variant.',('bgc',),'f1'),('taxonomy','taxon_classification.py','Taxonomic family','multiclass classification','Top ten BGC-rich taxonomic families; include/exclude remaining or unclassified families as a variant.',('bgc',),'f1'),('cds','cds_annotation.py','CDS versus intergenic nucleotide','dense binary classification','80 BGCs; sample ten per available biosynthetic class/prokaryote-eukaryote stratum, excluding Other; label every nucleotide from MIBiG annotations.',('cds','intergenic'),'mcc')]:
        ec=c.code('bgcs-'+slug+'-code',repo,'src/probing/'+file,'import ',desc)
        t='bgcs-'+slug
        c.task(t,'bgcs',target,'BGCs-Bench / MIBiG4',target,desc,typ,'MIBiG / TaxonKit / gene annotations',e,applications=('natural-products','microbial-genomics','genome-annotation'),capabilities=('dense-annotation',) if slug=='cds' else ('functional-prediction',),regions=regions,populations=('bacteria','euk'),input='BGC DNA; pooled or nucleotide-level frozen embeddings',limitations='Length-restricted, curated source. Long sequence inputs alone do not establish a measured distal dependency. Fold/taxon overlap and data counts are paper-reported until artifact verification.')
        p=c.protocol(t,t+'-probe','BGCs-Bench frozen logistic probe',e,'frozen probe','Layer-wise embeddings; mean/last-token pooling, strand and length variants','Five folds balance biosynthetic/taxonomic labels; annotation folds balance biosynthetic class and prokaryotic/eukaryotic composition. No family- or homology-disjoint split is established.','BGC',metrics=((metric,'Macro-F1 for sequence labels; nucleotide MCC for CDS'),),embeddings=True,fitted='One-vs-rest logistic regression; class-weighted; max_iter 1000 or 1500 for CDS',selection='Layer/pooling comparisons are explicit; blind validation selection is not established by reporting each layer.')
        c.field('protocols',p,'fitted_component',ec)
        if slug=='cds':
            c.count(t,80,'BGCs',e);c.count(t,2098355,'labeled bases',e)
        else:
            for name,length,n in [('66k','65,536 bp',2044),('131k','131,072 bp',2386)]:
                v=c.variant(t,t+'-'+name,name+' maximum input cohort',e,length='≤'+length);c.count(t,n,'BGCs',e,variant=v,qualifier='Paper-reported length-limited source cohort before task-specific class exclusions.')
        c.use('evo2',t,e,'bgcs','external-evaluation',protocol=p)
        c.use('ntv3',t,e,'bgcs','external-evaluation',protocol=p,note='Checkpoint generation/version must be matched to this paper; not assumed to be the October v2 model.')

def deepd(c):
    e=c.ev('deepd-human-regulatory','deepd-paper','Figure 4 and human regulatory classification results','Frozen-embedding classifiers for human core-promoter, promoter, splice-site and five TF-binding tasks; AUROC.')
    for slug,target,regions in [('core-promoter','Core-promoter detection',('promoter',)),('promoter','Promoter detection',('promoter',)),('splice','Splice-site detection',('splice',)),('human-tf','Human TF binding',('tfbs',))]:
        t='deepd-'+slug
        c.task(t,'deepd-evals',target,'DeepD human regulatory datasets',target,'Classify the specified regulatory annotation from frozen DeepD sequence representations. Source dataset identity and split manifests require supplementary reconciliation.','binary classification','Regulatory annotation / binding assays',e,applications=('genome-annotation','regulatory-engineering','gene-therapy'),capabilities=('functional-prediction',),regions=regions,populations=('human',),input='DNA sequence → frozen embeddings',status='panel-pending' if slug=='human-tf' else 'paper-audited',limitations='The main text establishes the target and frozen-classifier procedure, but not complete dataset lineage, counts or split construction. TF panel requires five individual dataset identities.')
        p=c.protocol(t,t+'-probe','DeepD human regulatory probe',e,'frozen probe','Frozen model embeddings','Exact train/validation/test construction not provided in accessible main-text detail.','sequence; grouping unresolved',metrics=('auroc',),embeddings=True,fitted='Downstream classifier; full architecture pending')
        c.use('deepd',t,e,'deepd',protocol=p)
    for t in c.rows['tasks']:
        if t['id'].startswith('deepd-annotation-'):
            t['status']='panel-pending';t['limitations']+=' Per-annotation binary target decomposition is pending.'
    eg=c.ev('deepd-promoter-counts','deepd-paper','Figure 6B–C, candidate pools and experimental validation','450 High and 450 Low generated candidate pools; 83 High and 71 Low experimentally tested, three biological replicates per candidate.')
    for label,n,split in [('High',450,'predicted candidate pool'),('Low',450,'predicted candidate pool'),('High',83,'dual-luciferase validation'),('Low',71,'dual-luciferase validation')]:
        c.count('deepd-maize-promoter',n,label+' candidates',eg,split=split,qualifier='Pool and validation subset counts are separate, not additive.')

def parent_resources(c):
    gen=c.ev('generator-family-generation','generator-paper','Sections 2.6, 4.4; fine-tuning appendix','Cytochrome P450 and histone family-specific coding-DNA generation; RefSeq/UniProt mappings and computational sequence/protein validation.')
    for slug,family in [('p450','Cytochrome P450'),('histone','Histone')]:
        t='generator-family-'+slug
        c.task(t,'generator-evals',family+' coding-sequence generation','RefSeq / UniProt '+family,family+' generated coding sequence','Fine-tune on family coding DNA; assess generated ORFs, translated protein similarity, embedding distributions and predicted structures. These are computational plausibility checks.','generation','Family annotation; computational validation',gen,applications=('protein-engineering',),capabilities=('generation','conditional-generation'),regions=('cds',),input='Family-specific fine-tuned generative model',output='Generated coding DNA / translated protein',limitations='No new enzyme activity or organismal function measurement is established by these diagnostics. Sequence deduplication is not a held-out-family test.')
        c.protocol(t,t+'-protocol','Family-specific GENERator sampling',gen,'family-specific fine-tune + sampling','Autoregressive coding-DNA decoder','Train on RefSeq-linked family CDS. Remove sequences duplicated with training; no unseen-family transfer is claimed.','coding sequence / family',embeddings=False,notes='Unique generated samples, embedding comparisons and predicted structures are separate validation endpoints.')
        c.use('generator',t,gen,'generator')
    eq=c.ev('ntv3-eqtl-chromosomes','ntv3-paper','Methods 4.8, GTEx eQTL evaluation','Zero-shot test chromosomes 3,6,9,12,16,18,19,21; 1-Mb allele-centered input, exon-averaged RNA-seq outputs and maximum absolute fold change across tracks/genes.')
    p=next(p for p in c.rows['protocols'] if p['id']=='ntv3-eqtl-protocol')
    p['split_rule']='Variants restricted to zero-shot test chromosomes 3,6,9,12,16,18,19,21. Per-tissue classification across 48 tissues; 400 tissue-stratified bootstrap resamples.'
    p['model_interface']='1,048,576-bp allele-centered DNA; exon-averaged native RNA-seq signal, forward/reverse average; largest absolute log fold change across tissue-matched tracks and genes.'
    c.field('protocols',p['id'],'split_rule',eq)
    c.field('protocols',p['id'],'model_interface',eq)
    c.source('proteingym-paper','ProteinGym: Large-Scale Benchmarks for Protein Fitness Prediction and Design','https://pmc.ncbi.nlm.nih.gov/articles/PMC10723403/','paper','NeurIPS 2023')
    c.paper('proteingym','ProteinGym: Large-Scale Benchmarks for Protein Fitness Prediction and Design','proteingym-paper',2023,status='conference',scope='benchmark',notes='Parent resource registration. gLM-specific nucleotide conversions and selected subsets are independently described by the evaluating paper.')
    ep=c.ev('proteingym-parent','proteingym-paper','Benchmark resource and versioned data releases','Protein variant fitness/design resource; gLM papers select subsets and construct nucleotide representations differently.')
    c.suite('proteingym','ProteinGym','Parent protein-variant resource. Current catalogue links selected gLM panels rather than claiming all ProteinGym assays are nucleotide-ready.',ep,'proteingym',status='partial',notes='GPN-Star v0.1 human single-SNV-accessible conversion and Evo 2 nucleotide-study collections are different protocols.')
    for t in c.rows['tasks']:
        if t['id'].startswith('evo-dms-') or t['id']=='gpn-proteingym':c.member('proteingym',t['id'],t['evidence_id'],'Selected upstream subset; do not assume complete ProteinGym coverage.')
    # Make named external resources discoverable without making them model papers.
    e=c.ev('named-resource-links','ntv3-paper','Methods 4.7–4.8','External named benchmark datasets have distinct targets and task-specific processing.')
    for sid,name,description,taskids in [('seiplant','SeiPlant','Plant histone-mark transfer source.',('ntv3-seiplant',)),('deepfarm','DeepFARM','Livestock chromatin peak classification source.',('ntv3-deepfarm',)),('daniodecima','DanioDecima','Zebrafish pseudobulk expression source.',('ntv3-danio',)),('re2g','ENCODE-rE2G','Experimentally supported enhancer–gene links.',('ntv3-re2g',))]:
        c.suite(sid,name,description,e,status='partial',notes='Individual task records cite the evaluating paper’s cohort; upstream release audit is separate.')
        for t in taskids:c.member(sid,t,e)
